<script setup>
import { Head, Link, useForm } from '@inertiajs/vue3'
import AppShell from '../../Layouts/AppShell.vue'

defineOptions({ layout: AppShell })
const props = defineProps({ asset: Object, classifications: Array, locations: Array, units: Array, fundingSources: Array })
const form = useForm({ classification_id: props.asset?.classification_id || '', asset_code: props.asset?.asset_code || '', register_number: props.asset?.register_number || '', name: props.asset?.name || '', description: props.asset?.description || '', quantity: props.asset?.quantity || 1, unit_id: props.asset?.unit_id || '', acquisition_value: props.asset?.acquisition_value || '', current_location_id: props.asset?.current_location_id || '', condition: props.asset?.condition || 'good', lock_version: props.asset?.lock_version })
const submit = () => form[props.asset ? 'patch' : 'post'](props.asset ? `/assets/${props.asset.uuid}` : '/assets')
</script>

<template><Head :title="asset ? 'Edit aset' : 'Tambah aset baru'" /><main class="mx-auto max-w-5xl space-y-6 px-4 py-8 sm:px-6"><header><Link href="/assets" class="text-sm font-medium text-blue-700"><- Kembali ke daftar aset</Link><h1 class="mt-3 text-3xl font-bold tracking-tight">{{ asset ? 'Edit informasi aset' : 'Tambah aset baru' }}</h1><p class="mt-2 text-slate-600">Perubahan lokasi, kondisi, klasifikasi, dan lifecycle tetap melalui aksi historis.</p></header><form @submit.prevent="submit" class="grid gap-4 rounded-2xl border border-slate-200 bg-white p-6 shadow-sm"><label class="text-sm font-medium">Nama<input v-model="form.name" required class="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2"></label><label class="text-sm font-medium">Kode aset<input v-model="form.asset_code" class="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2"></label><label class="text-sm font-medium">Nomor register<input v-model="form.register_number" class="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2"></label><label class="text-sm font-medium">Klasifikasi<select v-model="form.classification_id" required class="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2"><option value="">Pilih klasifikasi</option><option v-for="x in classifications" :key="x.id" :value="x.id">{{ x.code }} - {{ x.name }}</option></select></label><label class="text-sm font-medium">Satuan<select v-model="form.unit_id" required class="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2"><option value="">Pilih unit</option><option v-for="x in units" :key="x.id" :value="x.id">{{ x.code }} - {{ x.name }}</option></select></label><label class="text-sm font-medium">Jumlah<input v-model="form.quantity" type="number" min="0.01" step="0.01" required class="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2"></label><label class="text-sm font-medium">Nilai perolehan (Rp)<input v-model="form.acquisition_value" type="number" min="0" step="0.01" class="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2"></label><label class="text-sm font-medium">Lokasi<select v-model="form.current_location_id" class="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2"><option value="">Belum ditentukan</option><option v-for="x in locations" :key="x.id" :value="x.id">{{ x.code }} - {{ x.name }}</option></select></label><label class="text-sm font-medium">Kondisi<select v-model="form.condition" required class="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2"><option value="good">Baik</option><option value="damaged">Rusak</option><option value="broken">Rusak berat</option></select></label><label class="text-sm font-medium">Deskripsi<textarea v-model="form.description" rows="4" class="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2"></textarea></label><p v-if="form.errors && Object.keys(form.errors).length" class="text-sm text-red-700">Periksa kembali input yang ditandai server.</p><button :disabled="form.processing" class="rounded-lg bg-[#0B2E5B] px-5 py-2.5 font-bold text-white disabled:opacity-50">Simpan</button></form></main></template>
